window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q07"]=window.__LIBQ["the-gioi-hoan-my"]["q07"]||{};window.__LIBQ["the-gioi-hoan-my"]["q07"]["map"]={"updatedAt":"2026-07-22","count":157,"nodes":[{"id":"ngon-nui-thap-gan-thach-thon","name":"Ngọn núi thấp gần Thạch thôn","cn":"","capDo":"khac","parentId":"thach-thon","blurb":"Ngọn núi thấp nơi người Thạch thôn an táng Thạch Hạo.","detail":"Sau hơn ba tháng kể từ khi Thạch Hạo được chôn cất, thảm thực vật trên núi phát triển và linh khí dường như trở nên nồng đậm hơn. Thạch Lâm Hổ nhận ra biến đổi nhưng chưa xác định được nguyên nhân.","theLucLienQuan":["Thạch thôn"],"nguon":["@c0601"]},{"id":"thach-do","name":"Thạch Đô","cn":"","capDo":"thanh","parentId":"thach-quoc-dia-danh-c0192","blurb":"Kinh đô Thạch Quốc và là nơi tổ chức quốc tang cho Thạch Hạo.","detail":"Thạch Đô tiếp đón nhiều quốc chủ, giáo chủ, kỳ tài thượng giới và hơn mười vị Tôn giả từ các đại vực đến cúng viếng Thạch Hạo.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0601"]},{"id":"than-vien-ma-quy","name":"Thần viên Ma Quỳ","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Khu vực thượng giới mọc một vùng lớn Ma Quỳ màu đen.","detail":"Tin toàn bộ sinh linh vượt giới bị tiêu diệt truyền đến nơi này, khiến Ma Quỳ Viên phản ứng trước thất bại của kế hoạch hạ giới.","theLucLienQuan":["Ma Quỳ Viên"],"nguon":["@c0601"]},{"id":"minh-tho-dia-danh","name":"Minh Thổ","cn":"","capDo":"vuc","parentId":"thuong-gioi","blurb":"Vùng đất thượng giới phủ đầy tử khí và sương đen, cũng là địa bàn của thế lực Minh Thổ.","detail":"Tại đây, thế lực Minh Thổ biết toàn bộ nhân mã vượt giới đã bị diệt và những tài nguyên bỏ ra cho kế hoạch hạ giới trở thành công cốc.","theLucLienQuan":["Minh Thổ"],"nguon":["@c0601"]},{"id":"thu-vien-tao-hoa-dia-danh","name":"Thư viện Tạo Hóa","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Học phủ rộng lớn ở thượng giới, tập trung nhiều cường giả trẻ tuổi.","detail":"Đây là nơi học viên bàn luận tin thiếu niên hạ giới đã tiêu diệt toàn bộ nhân mã của ba thế lực lớn rồi chết trận.","theLucLienQuan":["Thư viện Tạo Hóa"],"nguon":["@c0601"]},{"id":"hoc-vien-sinh-menh-dia-danh","name":"Học viện Sinh Mệnh","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Học viện thượng giới có nhiều nữ học viên quan tâm đến thiên tài hạ giới.","detail":"Các nữ học viên tại đây từng muốn chiêu mộ thiếu niên đã chém nhiều ngụy Thần, trước khi biết con đường từ thượng giới xuống hạ giới đã bị cắt hoàn toàn.","theLucLienQuan":["Học viện Sinh Mệnh"],"nguon":["@c0601"]},{"id":"than-vien-cuu-tieu-dia-danh","name":"Thần viện Cửu Tiêu","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Học viện tọa lạc trên trời cao ở thượng giới.","detail":"Người trẻ tại thần viện nhận tin Thạch Hạo chết trận và bàn luận việc pháp tắc thiên đạo đang siết chặt con đường qua lại giữa hai giới.","theLucLienQuan":["Thần viện Cửu Tiêu"],"nguon":["@c0601"]},{"id":"bat-lao-son-dia-danh","name":"Bất Lão Sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Tần Hạo ở sau khi dung hợp Chí Tôn cốt.","detail":"Sau khi tin Tần Hạo sở hữu hai khối Chí Tôn cốt lan truyền, các kỳ tài và quý nữ thượng giới cùng đến đây bái phỏng và kết giao với hắn.","theLucLienQuan":["Bất Lão Sơn"],"nguon":["@c0601"]},{"id":"thien-van-chau","name":"Thiên Vẫn châu","cn":"","capDo":"chau","parentId":null,"blurb":"Một châu tại thượng giới, nơi xuất hiện cường giả trẻ tuổi quét ngang cùng thế hệ.","detail":"Một cường giả khoảng mười tám, mười chín tuổi từng quét ngang những người cùng thế hệ tại Thiên Vẫn châu trước khi gia nhập Thư viện Thiên Vẫn.","theLucLienQuan":["Thư viện Thiên Vẫn"],"nguon":["@c0602"]},{"id":"mo-thach-hao","name":"Mộ Thạch Hạo","cn":"","capDo":"khac","parentId":"ngon-nui-thap-gan-thach-thon","blurb":"Ngôi mộ đặt quan tài Thạch Hạo, được một vùng cỏ Bất Hủ bao quanh.","detail":"Bên dưới mộ, rễ cỏ Bất Hủ quấn quan tài thành một cái kén và phát ra dao động luân hồi. Sau hai tháng, mộ đất, kén rễ và quan tài lần lượt nứt vỡ, để lộ thân thể Thạch Hạo đang khôi phục dấu hiệu sống.","theLucLienQuan":["Thạch thôn"],"nguon":["@c0603"]},{"id":"minh-gioi","name":"Minh giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Nơi duy nhất được nói là có cỏ Luân Hồi sinh trưởng.","detail":"Cỏ Luân Hồi được cho là chỉ sinh trưởng tại Minh giới, từng được Thập hung lấy ra để tham gia quá trình lai tạo cỏ Bất Hủ.","theLucLienQuan":[],"nguon":["@c0603"]},{"id":"hang-chan-long","name":"Hang Chân Long","cn":"","capDo":"khac","parentId":null,"blurb":"Một loại cổ địa đặc biệt có môi trường phù hợp cho cỏ Bất Hủ sinh trưởng.","detail":"Hang Chân Long được nhắc như một trong số ít bảo địa có điều kiện tự nhiên đủ đặc biệt để nuôi sống cỏ Bất Hủ.","theLucLienQuan":[],"nguon":["@c0603"]},{"id":"o-than-hoang","name":"Ổ Thần Hoàng","cn":"","capDo":"khac","parentId":null,"blurb":"Bảo địa được cho là có môi trường thích hợp để cỏ Bất Hủ sinh trưởng.","detail":"Ổ Thần Hoàng được nhắc cùng hang Chân Long như một cổ địa đặc biệt có thể nuôi sống cỏ Bất Hủ.","theLucLienQuan":[],"nguon":["@c0603"]},{"id":"linh-ho-thach-thon","name":"Linh hồ Thạch thôn","cn":"","capDo":"khac","parentId":"thach-thon","blurb":"Hồ nước được đại trận bảo vệ trong Thạch thôn, nơi nuôi nhiều loài linh vật quý.","detail":"Linh hồ vốn có Long Tu ngư. Thạch Hạo bổ sung mấy trăm con Ngân Linh thu và tám con ba ba già màu vàng, biến nơi đây thành nguồn linh vật và dược liệu lâu dài cho tộc nhân.","theLucLienQuan":["Thạch thôn"],"nguon":["@c0607"]},{"id":"to-te-dan-hoang-cung-thach-quoc","name":"Tổ tế đàn hoàng cung Thạch Quốc","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Tế đàn mở thông đạo để Thanh Phong và Thạch Hạo xuất hiện tại hoàng cung.","detail":"Tổ tế đàn trong hoàng cung phát sáng và mở thông đạo. Thanh Phong bước ra trước, sau đó Thạch Hạo xuất hiện trước các lão Vương và thị vệ, xác nhận vị Thạch Hoàng từng bị cho là đã chết vẫn còn sống.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0608"]},{"id":"son-mon-bat-lao-son","name":"Sơn môn Bất Lão Sơn","cn":"","capDo":"khac","parentId":"bat-lao-son-dia-danh","blurb":"Tuyến phòng thủ phía ngoài của Bất Lão Sơn tại Huyền Vực. Nơi này bị Đả Thần Thạch cùng tam vương Thạch Quốc phá trận và đánh sập.","detail":"Linh thân của Thạch Hạo từng bí mật giám sát khu vực bên ngoài sơn môn. Khi đại quân Thạch Quốc kéo đến, Bất Lão Sơn đóng cửa và mở hộ sơn thần trận, nhưng phòng tuyến nhanh chóng bị phá, mở đường cho quân Thạch Quốc tràn vào.","theLucLienQuan":["Bất Lão Sơn","Thạch Quốc","Tần tộc"],"nguon":["@c0611"]},{"id":"tru-vuc","name":"Trụ Vực","cn":"","capDo":"vuc","parentId":null,"blurb":"Một đại vực có lãnh thổ mênh mông, dân cư đông đúc cùng nhiều đạo thống và môn phái.","detail":"Bổ Thiên Giáo là truyền thừa nổi danh nhất tại Trụ Vực. Thạch Hạo cùng quân Thạch Quốc dùng truyền tống trận của Tần tộc vượt vực tới đây để tiến đánh giáo này.","theLucLienQuan":["Bổ Thiên Giáo","Thạch Quốc"],"nguon":["@c0612"]},{"id":"son-mon-bo-thien-giao","name":"Sơn môn Bổ Thiên Giáo","cn":"","capDo":"khac","parentId":"tru-vuc","blurb":"Cửa ngõ của Bổ Thiên Giáo tại Trụ Vực, được pháp trận cấp thần và cốt văn bảo vệ.","detail":"Linh thân Chân Hoàng của Thạch Hạo từng bị phòng tuyến tại đây ngăn cản. Sau đó Thạch Hạo dùng đỉnh nhỏ màu bạc cùng năm pháp khí thần linh phá trận và đánh sơn môn thành bột mịn.","theLucLienQuan":["Bổ Thiên Giáo","Thạch Quốc"],"nguon":["@c0612"]},{"id":"trung-tam-thanh-dia-bo-thien-giao","name":"Trung tâm thánh địa Bổ Thiên Giáo","cn":"","capDo":"khac","parentId":"son-mon-bo-thien-giao","blurb":"Khu vực trung tâm của Bổ Thiên Giáo, nơi các đảo nổi hợp thành Bổ Thiên trận.","detail":"Bên trong thánh địa có vườn thuốc, linh tuyền, linh thảo và nhiều cây kỳ dược hiếm có. Sau khi Bổ Thiên trận bị phá, toàn bộ khu vực cùng tài nguyên trọng yếu rơi vào tay Thạch Quốc.","theLucLienQuan":["Bổ Thiên Giáo","Thạch Quốc"],"nguon":["@c0612"]},{"id":"co-dien-tay-phuong-giao","name":"Cổ điện Tây Phương Giáo","cn":"","capDo":"khac","parentId":null,"blurb":"Một cổ điện nằm trên linh sơn trong Tây Phương Giáo.","detail":"Bên trong cổ điện có thần trì chưa tới một thước vuông chứa lượng lớn Kim Cương dịch. Một cây bảo xử hàng ma được đặt cạnh thần trì để trấn áp bảo dịch.","theLucLienQuan":["Tây Phương Giáo","Thạch Quốc"],"nguon":["@c0612"]},{"id":"tieu-the-gioi-tieu-tay-thien","name":"Tiểu thế giới Tiểu Tây Thiên","cn":"","capDo":"gioi-nho","parentId":"hoang-vuc","blurb":"Tiểu thế giới do Thần tạo, từng là căn cơ của Tiểu Tây Thiên.","detail":"Cửa vào bị Hàng Ma Bảo Xử đánh xuyên. Bên trong có ruộng linh dược, Hỏa Diễm Động và ao bùn nuôi linh trùng quý; sau trận chiến, toàn khu vực trở thành thành trì của Thạch Quốc.","theLucLienQuan":["Tiểu Tây Thiên","Thạch Quốc"],"nguon":["@c0613"]},{"id":"bien-cuong-phia-tay-thach-quoc","name":"Biên cương phía tây Thạch Quốc","cn":"","capDo":"khac","parentId":"thach-quoc-dia-danh-c0192","blurb":"Khu vực phía tây Thạch Quốc, nơi có lối vào Tiểu Tây Thiên.","detail":"Sau khi vượt vực bích trở lại Hoang Vực, chiến thuyền Thạch Quốc không về Thạch Đô mà tiến thẳng tới đây để tấn công Tiểu Tây Thiên.","theLucLienQuan":["Thạch Quốc","Tiểu Tây Thiên"],"nguon":["@c0613"]},{"id":"hoa-diem-dong","name":"Hỏa Diễm Động","cn":"","capDo":"khac","parentId":"tieu-the-gioi-tieu-tay-thien","blurb":"Khu bồi dưỡng dược liệu hệ hỏa trong Tiểu Tây Thiên.","detail":"Nơi này nuôi trồng Ly Hỏa Linh Hoa, Chu Tước Lan và Xích Quang Thảo, sau đó bị Thạch Quốc thu nhận cùng các tài nguyên của Tiểu Tây Thiên.","theLucLienQuan":["Tiểu Tây Thiên","Thạch Quốc"],"nguon":["@c0613"]},{"id":"co-mieu-dong-trong-nui-sau","name":"Cổ miếu đồng trong núi sâu","cn":"","capDo":"khac","parentId":"hoang-vuc","blurb":"Bí địa do tư liệu Tây Phương Giáo ghi lại, có kiến trúc bằng đồng phủ gỉ xanh và một truyền tống trận đã bị hủy.","detail":"Thạch Hạo nhận ra dấu vết nguyền rủa giống Tiên Điện tại cổ miếu và nghi ngờ người của truyền thừa này từng biến nơi đây thành tử địa.","theLucLienQuan":["Tây Phương Giáo","Tiên Điện"],"nguon":["@c0614"]},{"id":"mat-dia-luu-chu-cua-nguyet-thien","name":"Mật địa lưu chữ của Nguyệt Thiền","cn":"","capDo":"khac","parentId":"tru-vuc","blurb":"Mật địa tại Trụ Vực nơi thứ thân Nguyệt Thiền để lại lời từ biệt hạ giới trước khi dùng bí lộ lên thượng giới.","detail":"Thạch Hạo nhận ra nét chữ của thứ thân Nguyệt Thiền và xác định nàng đã không trở về Bổ Thiên Giáo. Pháp trận tại đây bị hủy sau một lần vận hành.","theLucLienQuan":["Bổ Thiên Giáo"],"nguon":["@c0614"]},{"id":"hai-than-dao","name":"Hải Thần Đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Đảo lớn có bia ghi tên, là địa bàn của Hải Thần tộc và từng có đường liên giới.","detail":"Mạc Thương từng rời hạ giới qua con đường tại Hải Thần Đảo. Khi Thạch Hạo tới kiểm tra, Hải Thần tộc xác nhận con đường này đã bị cắt đứt.","theLucLienQuan":["Hải Thần tộc"],"nguon":["@c0614"]},{"id":"cua-ai-thu-muoi-chien-truong-bach-toc","name":"Cửa ải thứ mười của Chiến trường Bách Tộc","cn":"","capDo":"khac","parentId":"chien-truong-bach-toc-dia-danh","blurb":"Cửa cuối của Chiến trường Bách Tộc, nơi còn một truyền tống trận hoàn hảo có thể nối tới thượng giới.","detail":"Lời cảnh báo tại cửa ải cho biết đầu bên kia là lồng giam, nơi sinh linh hạ giới có nguy cơ bị bắt làm tọa kỵ. Thạch Hạo vì thế quyết định quay về.","theLucLienQuan":[],"nguon":["@c0614"]},{"id":"than-ma-chi-tuong","name":"Thần Ma chi tường","cn":"","capDo":"khac","parentId":null,"blurb":"Bức tường cổ gồm một trăm lẻ tám cửa, mở ra con đường khảo nghiệm cực kỳ nguy hiểm. Thạch Hạo suy đoán cổ lộ phía sau có thể liên quan tới thượng giới hoặc Vùng cấm thần bí.","detail":"Bức tường Thần Ma chân chính nằm sâu trong vùng cấm rừng rậm màu đen. Sinh linh tại các cửa mạnh hơn rõ rệt so với đối thủ trong Sân thi đấu Thánh Hoàng Cung, khiến người xông ải phải trải qua những cuộc chiến sinh tử.","theLucLienQuan":[],"nguon":["@c0615"]},{"id":"thanh-hoang-cung-thuong-co","name":"Thánh Hoàng Cung Thượng cổ","cn":"","capDo":"khac","parentId":"to-dia-hoa-quoc","blurb":"Cung điện khổng lồ nằm sâu dưới cổ địa Hỏa Quốc. Nơi đây chứa một bức tường Thần Ma thất bại và hệ thống Sân thi đấu dùng làm khảo nghiệm ban đầu.","detail":"Thạch Hạo trở lại cung điện để truy tìm manh mối về bức tường chân chính. Sau khi vượt hết các cửa khảo nghiệm, hắn được một pháp trận đưa tới vùng cấm rừng rậm màu đen.","theLucLienQuan":["Hỏa Quốc"],"nguon":["@c0615"]},{"id":"san-thi-dau-thanh-hoang-cung","name":"Sân thi đấu Thánh Hoàng Cung","cn":"","capDo":"khac","parentId":"thanh-hoang-cung-thuong-co","blurb":"Những đấu trường màu đỏ sậm nằm sau các cửa đá trong Thánh Hoàng Cung Thượng cổ. Mỗi nơi chứa hình chiếu hoặc đạo phù của cự hung cổ đại cùng cảnh giới với người vượt ải.","detail":"Các Sân thi đấu là giai đoạn khảo nghiệm ban đầu trên con đường dẫn tới bức tường Thần Ma chân chính. Một số đấu trường còn lưu giữ cốt văn ghi lại manh mối về vị trí của bức tường.","theLucLienQuan":["Hỏa Quốc"],"nguon":["@c0615"]},{"id":"vung-cam-rung-ram-mau-den","name":"Vùng cấm rừng rậm màu đen","cn":"","capDo":"vuc","parentId":"hoang-vuc","blurb":"Tuyệt địa của Hoang vực có vô số pháp trận, thần trận, động phủ cổ và truyền thừa tàn khuyết. Nơi sâu nhất cất giấu bức tường Thần Ma chân chính.","detail":"Pháp trận cuối Sân thi đấu đưa Thạch Hạo tới khu rừng này. Đả Thần Thạch phải hỗ trợ nghiên cứu các trận pháp nguy hiểm để cả hai tiến sâu, trong khi Đại ma thần Thập Ngũ Gia từng bị giam tại đây nhiều năm sau khi vào rừng lánh nạn.","theLucLienQuan":[],"nguon":["@c0615"]},{"id":"vuc-sau-sau-than-ma-chi-tuong","name":"Vực sâu sau Thần Ma chi tường","cn":"","capDo":"khac","parentId":"than-ma-chi-tuong","blurb":"Vực sâu tối đen nằm phía sau đoạn Thần Ma chi tường bị cắt đứt.","detail":"Vực lớn thông xuống lòng đất và lưu lại dấu chân khổng lồ được Đả Thần Thạch nhận định là của một con rùa lớn.","theLucLienQuan":["Cung điện Chí Tôn"],"nguon":["@c0616"]},{"id":"van-thien-cung","name":"Vân Thiên cung","cn":"","capDo":"khac","parentId":"ha-gioi","blurb":"Nơi cư trú cũ của Vân tộc.","detail":"Địa danh này từng được đôi tỷ muội song sinh nhắc với Thạch Hạo khi còn nhỏ và trở thành đầu mối giúp hắn tìm di chỉ Vân tộc.","theLucLienQuan":["Vân tộc"],"nguon":["@c0616"]},{"id":"di-chi-van-toc","name":"Di chỉ Vân tộc","cn":"","capDo":"khac","parentId":"van-thien-cung","blurb":"Quần thể kiến trúc còn nguyên vẹn của Vân tộc trên một ngọn núi cao phủ tuyết.","detail":"Bên dưới di chỉ có địa cung bị phong ấn, trong đó lưu lại cổ trận truyền tống từng được Vân tộc sử dụng để rời đi.","theLucLienQuan":["Vân tộc"],"nguon":["@c0616"]},{"id":"vung-nui-nam-khong-lo","name":"Vùng núi nấm khổng lồ","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Một hiểm địa tại thượng giới mọc đầy những cây nấm khổng lồ có ánh sáng ăn mòn thần lực.","detail":"Những cây nấm tại đây lớn như phòng ốc, có màu sắc sặc sỡ và tỏa ra quang vụ có thể bào mòn thần lực. Nhiều bộ xương trắng nằm dưới gốc nấm, còn khu vực xung quanh gần như không có dã thú dù mang nặng mùi máu.","theLucLienQuan":[],"nguon":["@c0617"]},{"id":"chu-thon","name":"Chu thôn","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Thôn xóm thượng giới có hơn nghìn hộ, nằm giữa hai núi đá được mạng nhện rộng khoảng hai dặm nối liền. Phía sau thôn là nơi Thạch Hạo dựng hồ Niết bàn.","detail":"Chu thôn có nhiều đội săn và được Tế linh nhện trắng bạc ở cảnh giới Hóa Linh bảo vệ. Đội săn đưa Thạch Hạo bị thương về đây và Tam a công cho hắn tạm trú.","theLucLienQuan":["Chu thôn"],"nguon":["@c0618"]},{"id":"khu-khong-nguoi","name":"Khu không người","cn":"","capDo":"vuc","parentId":"thuong-gioi","blurb":"Những vùng bí ẩn nằm ngoài phạm vi thường được thăm dò của thượng giới. Sự tồn tại của chúng khiến cương vực thực tế lớn hơn khái niệm ba nghìn châu.","detail":"Ngay cả số lượng châu của thượng giới cũng chưa chắc đã được xác định đầy đủ vì bên ngoài còn nhiều khu không người chưa thể khám phá.","theLucLienQuan":[],"nguon":["@c0618"]},{"id":"phu","name":"Phủ","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Một cấp khu vực trong hệ thống tuyển chọn dũng sĩ, nằm trên Thành và dưới Châu. Người mạnh nhất từng xuất thân từ vùng Chu thôn trước kia cũng chỉ dừng bước ở cấp này.","detail":"Người dự tuyển phải vượt qua các vòng từ Thôn lên Thành, Phủ rồi Châu trước khi có thể tiến xa hơn trong kỳ đại chiến.","theLucLienQuan":[],"nguon":["@c0618"]},{"id":"hoe-thanh","name":"Hòe thành","cn":"","capDo":"thanh","parentId":"loi-chau","blurb":"Một thị trấn tại Lôi châu có thể chứa vài vạn người, mang tên cây cổ hòe Tế linh trước cửa thành.","detail":"Hòe thành là nơi tổ chức tuyển chọn dũng sĩ cho các thôn xóm quanh vùng. Khi sứ giả Phủ thành tới, nơi đây đồng thời trở thành trung tâm điều tra tung tích cô gái tóc bạc.","theLucLienQuan":["Phủ thành","Chu thôn","Mãng thôn"],"nguon":["@c0620"]},{"id":"van-chau","name":"Vân châu","cn":"","capDo":"chau","parentId":null,"blurb":"Một châu vực thượng giới gắn với Vân tộc.","detail":"Vân tộc nắm giữ đạo thống tại Vân châu. Thạch Hạo vốn cho rằng truyền tống trận của Vân tộc sẽ đưa mình tới gần châu vực này.","theLucLienQuan":["Vân tộc"],"nguon":["@c0620"]},{"id":"loi-chau","name":"Lôi châu","cn":"","capDo":"chau","parentId":null,"blurb":"Châu vực thượng giới nơi Hòe thành và Chu thôn tọa lạc.","detail":"Lôi châu nằm ngoài địa bàn Vân tộc. Thạch Hạo suy đoán vụ nổ đường hầm hư không đã khiến mình lệch khỏi Vân châu và xuất hiện tại đây.","theLucLienQuan":["Chu thôn","Mãng thôn","Phủ thành"],"nguon":["@c0620"]},{"id":"san-dien-vo-hoe-thanh","name":"Sân diễn võ Hòe thành","cn":"","capDo":"khac","parentId":"hoe-thanh","blurb":"Khu vực rộng lớn ở trung tâm Hòe thành, được dùng làm nơi tuyển chọn dũng sĩ.","detail":"Trước khi cuộc tuyển chọn bắt đầu, sân diễn võ được nữ sứ giả Phủ thành và lão thành chủ dùng để công khai bức tranh cô gái tóc bạc, triệu tập các đầu lĩnh địa phương và dò hỏi tung tích nàng.","theLucLienQuan":["Phủ thành","Chu thôn","Mãng thôn"],"nguon":["@c0620"]},{"id":"ba-ngan-chau","name":"Ba ngàn châu","cn":"","capDo":"vuc","parentId":null,"blurb":"Phạm vi rộng lớn của thượng giới, nơi các thiên kiêu và đạo thống được đánh giá trên quy mô toàn cõi.","detail":"Ba ngàn châu được dùng làm phạm vi đánh giá địa vị và phong thái gần như vô địch của đại nhân trẻ tuổi Tiên Điện.","theLucLienQuan":["Tiên Điện"],"nguon":["@c0621"]},{"id":"day-nui-quanh-hoe-thanh","name":"Dãy núi quanh Hòe thành","cn":"","capDo":"vuc","parentId":"hoe-thanh","blurb":"Khu vực núi rộng lớn quanh Hòe thành, nơi nhiều cường giả và đại giáo tìm kiếm cô gái tóc bạc.","detail":"Khu vực trải rộng hàng nghìn dặm bị nhiều thế lực lục soát vì tin cô gái tóc bạc đang ẩn náu tại đây. Đằng Nhất giao chiến với đàn Hoàng Kim Nghĩ trong vùng núi, còn hai tổ hợp thiên kiêu đối đầu nhau ở sâu bên trong.","theLucLienQuan":["Tiên Điện","Bổ Thiên Giáo","Tộc Hỏa Kim","Tộc Hoàng Kim Nghĩ"],"nguon":["@c0622"]},{"id":"khu-vuc-nui-bi-phong-toa","name":"Khu vực núi bị phong tỏa","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Khu vực núi nơi các sơ đại giao phong và đoàn người tiếp tục truy tìm cô gái tóc bạc bị thương.","detail":"Chung quanh khu vực được cho là đã bị phong tỏa hoàn toàn. Sau khi các cuộc giao phong thăm dò kết thúc, nhiều người vẫn tin cô gái tóc bạc chưa thể thoát đi và đang ẩn náu dưỡng thương ở gần đó.","theLucLienQuan":["Tiên Điện"],"nguon":["@c0623"]},{"id":"suon-doc-da-gan-chu-thon","name":"Sườn dốc đá gần Chu thôn","cn":"","capDo":"khac","parentId":"chu-thon","blurb":"Sườn dốc có vách núi lấp lánh ánh bạc và một tổ chim cánh bạc.","detail":"Tổ chim trên sườn dốc được bện bằng linh mộc và lót Kim ti thảo. Đây là nơi Thạch Hạo phát hiện chim non toàn thân trắng bạc có linh tính khác thường.","theLucLienQuan":["Chu thôn"],"nguon":["@c0623"]},{"id":"khu-vuc-tim-kiem-co-gai-toc-bac","name":"Khu vực tìm kiếm cô gái tóc bạc","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực có nhiều tu sĩ qua lại để tìm kiếm cô gái tóc bạc.","detail":"Nơi này lưu lại dấu tích giao chiến của Nguyệt Thiền, Thiểm Điện Tử, Đằng Nhất và Chân Cổ. Một quái sư bói rằng cô gái tóc bạc vẫn chưa rời khỏi khu vực, khiến cuộc truy tìm tiếp tục căng thẳng.","theLucLienQuan":[],"nguon":["@c0624"]},{"id":"khu-vuc-hoe-thanh","name":"Khu vực Hòe thành","cn":"","capDo":"khac","parentId":"van-chau","blurb":"Vùng núi quanh Hòe thành nơi quần hùng hội tụ vì tin tức Tam Thế Đồng Quan và Cung Điện Chí Tôn.","detail":"Nhiều cường giả kéo tới đây tranh đoạt cơ duyên. Sau đó các đại giáo dựng đại trận phong ấn toàn khu vực để truy tìm cô gái tóc bạc.","theLucLienQuan":["Tiên Điện","Bổ Thiên Giáo"],"nguon":["@c0625"]},{"id":"ngu-hanh-chau","name":"Ngũ Hành Châu","cn":"","capDo":"chau","parentId":"ba-ngan-chau","blurb":"Một châu rộng lớn tiếp giáp Lôi châu và nằm dưới quyền chi phối của Bất Lão Sơn.","detail":"Thạch Hạo dùng truyền tống trận cổ liên châu rồi tiếp tục vượt qua nhiều truyền tống trận nội châu để tới đây tìm tin tức về Thập Ngũ Gia. Bất Lão Sơn có ảnh hưởng sâu rộng khắp châu.","theLucLienQuan":["Bất Lão Sơn","Tần tộc"],"nguon":["@c0625","@c0631","@c0679"]},{"id":"dao-ac-ma","name":"Đảo Ác Ma","cn":"","capDo":"khac","parentId":"ngu-hanh-chau","blurb":"Một địa điểm gồm vùng tuyệt địa và vùng lao tù giam giữ nhiều cường giả cùng ác ma.","detail":"Thạch Tử Lăng từng cùng nhiều người tới đảo tìm kiếm một người nhưng trở về thất vọng. Manh mối này khiến Thạch Hạo nghi Thập Ngũ Gia, thậm chí cả A Man, có thể đang mất tích hoặc bị giam tại đây.","theLucLienQuan":["Bất Lão Sơn"],"nguon":["@c0625","@c0631"],"aliases":["Ác Ma Đảo"]},{"id":"vung-suong-mu-tam-tram-dam","name":"Vùng sương mù tám trăm dặm","cn":"","capDo":"vuc","parentId":"dao-ac-ma","blurb":"Vành đai sương mù nguy hiểm bao quanh lối vào đảo Ác Ma.","detail":"Sương mù khiến người bình thường khó phi hành và rất dễ lạc đường. Những người tự dùng bảo cụ bay qua có thể bị thương nặng, trong khi cự thú thần bí còn ẩn nấp bên trong.","theLucLienQuan":[],"nguon":["@c0626"]},{"id":"khu-nha-tu-dao-ac-ma","name":"Khu nhà tù đảo Ác Ma","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Nửa đảo dùng để giam giữ và cưỡng ép các cường giả khai thác tài nguyên.","detail":"Nhà tù tối om được xây bằng hắc kim pha bảo liệu và gia cố bằng pháp trận bất hủ. Nơi đây giam cả sinh linh đã đốt Thần Hỏa lẫn Thiên Thần; tù nhân bị phong bế tu vi, xiềng xích và áp giải xuống hầm mỏ.","theLucLienQuan":[],"nguon":["@c0626"]},{"id":"cac-ham-mo-co-dao-ac-ma","name":"Các hầm mỏ cổ đảo Ác Ma","cn":"","capDo":"khac","parentId":"khu-nha-tu-dao-ac-ma","blurb":"Hệ thống hầm mỏ dưới lòng đảo chứa thần liệu lôi đạo và nhiều vật liệu quý hiếm.","detail":"Các mỏ bị sức mạnh nguyền rủa bao phủ và thường gây chết người. Người ngoài có thể tự nguyện thăm dò sau khi trả phí cao, nhưng phải nộp bảy phần thu hoạch.","theLucLienQuan":[],"nguon":["@c0626"]},{"id":"tuyet-dia-dao-ac-ma","name":"Tuyệt địa đảo Ác Ma","cn":"","capDo":"vuc","parentId":"dao-ac-ma","blurb":"Nửa đảo tự nhiên nguy hiểm, được cho là ẩn chứa đại tạo hóa và Mộ tiên.","detail":"Tuyệt địa nguy hiểm hơn khu nhà tù và có thể đe dọa cả những cường giả mạnh. Nhiều người tới đảo lựa chọn tiến vào đây để tìm kiếm cơ duyên trong truyền thuyết.","theLucLienQuan":[],"nguon":["@c0626"]},{"id":"mo-tien-dao-ac-ma","name":"Mộ tiên","cn":"","capDo":"khac","parentId":"tuyet-dia-dao-ac-ma","blurb":"Ngôi mộ trong truyền thuyết được cho là nằm sâu trong tuyệt địa đảo Ác Ma.","detail":"Mộ tiên được đồn thuộc về sinh linh cấm kỵ từng xuất hiện trong lôi đình tiên đạo và chết trong trận chiến với Ma tôn. Tin đồn về tiên huyết tại đây thu hút nhiều thiên tài tới tranh đoạt.","theLucLienQuan":[],"nguon":["@c0626"]},{"id":"khu-co-mo-dao-ac-ma","name":"Khu cổ mỏ đảo Ác Ma","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Hệ thống mỏ cổ trên đảo Ác Ma đã bị khai thác suốt hàng vạn năm.","detail":"Khu vực gồm các đại hầm mỏ chứa thần liệu, những nơi mở cho người ngoài khai thác và các mỏ quý nằm sâu dưới đất chỉ cho phạm nhân cấp Thần tiến vào. Nguyền rủa dưới lòng đất mạnh lên tùy theo tu vi của người khai thác.","theLucLienQuan":["Bất Lão Sơn","Tần tộc"],"nguon":["@c0627"]},{"id":"phe-mo-chua-ky-tran","name":"Phế mỏ chứa kỳ trân","cn":"","capDo":"khac","parentId":"khu-co-mo-dao-ac-ma","blurb":"Hầm mỏ cổ bỏ hoang nơi Thạch Hạo phát hiện một kỳ trân chưa rõ lai lịch.","detail":"Kỳ trân nằm trong tầng đá sâu nhất và tỏa hào quang cực thịnh. Thạch Hạo dùng Trùng Đồng nhìn thấy vật này rồi đánh thức Đả Thần Thạch để bàn cách khai quật.","theLucLienQuan":[],"nguon":["@c0627"]},{"id":"hac-nguc","name":"Hắc Ngục","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Nhà ngục trên đảo Ác Ma giam giữ nhiều người từng đối địch với Bất Lão Sơn.","detail":"Hắc Ngục được đồn còn trấn áp một số Chân Thần Thượng Cổ. Thạch Hạo dự tính phá mở nơi này và thả tù nhân để tạo đại loạn, qua đó thuận tiện đoạt kỳ trân trong phế mỏ.","theLucLienQuan":["Bất Lão Sơn"],"nguon":["@c0627"]},{"id":"dia-mach-dao-ac-ma","name":"Địa mạch đảo Ác Ma","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Hệ thống địa mạch dưới đảo Ác Ma chứa những tia chớp nguy hiểm, mảnh vỡ pháp tắc Tiên đạo và địa bảo lôi điện.","detail":"Đả Thần Thạch dùng Trùng đồng xác định lôi điện sâu trong địa mạch rồi dẫn sức mạnh này tới tầng ngoài Hắc ngục. Dưới tầng nham thạch còn có cây cỏ năm lá và hòn đá chứa lôi điện cùng phù văn màu vàng thần bí.","theLucLienQuan":["Tần tộc"],"nguon":["@c0628"]},{"id":"cot-thap-hai-dang","name":"Cốt tháp hải đăng","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Hệ thống cốt tháp có trận pháp bảo hộ nằm rải rác trong tuyệt địa đảo Ác Ma.","detail":"Những cốt tháp vốn là động phủ và trận pháp do người tu luyện đời trước để lại, sau được cải tạo thành tháp hải đăng để chỉ dẫn phương hướng, bảo vệ và cung cấp nơi nghỉ ngơi cho người thám hiểm. Càng tiến sâu vào đảo, số lượng cốt tháp càng ít, còn tòa cuối cùng đánh dấu ranh giới của khu vực nguy hiểm nhất.","theLucLienQuan":[],"nguon":["@c0629"]},{"id":"dong-song-tren-vom-troi","name":"Dòng sông trên vòm trời","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Dòng sông trắng bạc pha ánh vàng chảy giữa vòm trời sâu trong đảo Ác Ma.","detail":"Trong sông có nhiều thi thể cấp Thần và cả Thiên Thần đã chết từ lâu nhưng vẫn bất hủ. Lôi điện cùng sức mạnh nguyền rủa trong dòng sông biến việc tiếp cận thi thể để tìm truyền thừa thành hành động cực kỳ nguy hiểm; lai lịch của nó được giải thích bằng nhiều lời truyền nhưng chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c0629"]},{"id":"ngoi-mo-tien","name":"Ngôi mộ Tiên","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Địa điểm trong lời truyền được cho là nằm ở cuối dòng sông trên vòm trời.","detail":"Một cô gái bên dòng sông kể rằng toàn bộ dòng sông lớn chảy vào ngôi mộ Tiên này, nhưng sự tồn tại và vị trí thực tế của nó chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c0629"]},{"id":"co-thanh-cua-ma-ton","name":"Cổ thành của Ma tôn","cn":"","capDo":"thanh","parentId":"dao-ac-ma","blurb":"Phế tích cổ thành nằm sát bờ dòng sông trên trời, được cho là di tích do Ma tôn để lại.","detail":"Gần như toàn bộ kiến trúc trong thành đã sụp đổ, chỉ còn một đoạn tường thành và quảng trường cũ đặt bia khảo nghiệm cao ba ngàn trượng. Nơi đây lưu dấu tên của nhiều nhân vật nổi danh từng tiến vào tuyệt địa.","theLucLienQuan":[],"nguon":["@c0629"]},{"id":"bo-thien-ha","name":"Bờ thiên hà","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Khu vực ven dòng thiên hà trên đảo Ác Ma, nơi Lưu Danh Thần Bia cao ba ngàn trượng thu hút hàng trăm sinh linh tới khảo nghiệm.","detail":"Thần thi chìm nổi trong dòng thiên hà, còn Lưu Danh Thần Bia đứng bên bờ. Nhiều thiên tài tụ tập tại đây để kiểm tra sức chiến đấu hoặc thiên phú trước khi tiếp tục hành trình tìm kiếm vận may trên đảo Ác Ma.","theLucLienQuan":[],"nguon":["@c0630"]},{"id":"muoi-chau-quanh-than-bia","name":"Mười châu quanh thần bia","cn":"","capDo":"vuc","parentId":"ba-ngan-chau","blurb":"Khu vực gồm mười châu lân cận Lưu Danh Thần Bia, cung cấp phần lớn những người có tên trong bảng xếp hạng tích lũy từ cổ đại.","detail":"Do khoảng cách giữa các châu xa như tinh không, phần lớn thiên tài của Ba ngàn châu không thể tới khảo nghiệm. Vì vậy, ba triệu thứ hạng trên thần bia chủ yếu phản ánh kỳ tài của mười châu quanh khu vực này.","theLucLienQuan":[],"nguon":["@c0630"]},{"id":"thien-ha","name":"Thiên hà","cn":"","capDo":"khac","parentId":null,"blurb":"Thiên hà là dòng sông mà Thạch Hạo men theo để tiến về phía mộ Tiên.","detail":"Ven thiên hà có lôi điện và sóng lớn. Thạch Hạo vừa tiến sâu vừa quan sát phù văn của dị thảo màu vàng và tìm hiểu sức mạnh lôi đình.","theLucLienQuan":[],"nguon":["@c0631"]},{"id":"mo-tien","name":"Mộ Tiên","cn":"","capDo":"khac","parentId":null,"blurb":"Mộ Tiên là đích đến nằm sâu theo hướng thiên hà, nơi Thạch Hạo muốn tìm tạo hóa của bản thân.","detail":"Con đường tới mộ Tiên chịu ảnh hưởng của nguyền rủa tăng theo tu vi. Các nhân vật cấp Bá chủ không dám đuổi sâu, còn từ xưa chưa có ai tới được phần cuối.","theLucLienQuan":[],"nguon":["@c0631"]},{"id":"thien-ha-dao-ac-ma","name":"Thiên hà trên đảo Ác Ma","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Dòng sông lơ lửng chứa sức mạnh lôi đình dày đặc, Thần thi và Lôi Thần mộc. Ven sông là con đường Thạch Hạo dùng để tiến về phía Mộ Tiên.","detail":"Thiên hà chạy sâu vào đảo Ác Ma và là nơi nguyền rủa càng lúc càng mạnh. Lý Vân Thông từng mạo hiểm lấy Lôi Thần mộc tại đây, còn Thạch Hạo vừa tiến bước vừa cảm ngộ Lôi đạo.","theLucLienQuan":[],"nguon":["@c0632"]},{"id":"ngon-nui-da-co-loi-khac-thap-ngu-gia","name":"Ngọn núi đá bên thiên hà","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Ngọn núi đá lơ lửng bên thiên hà, có trận pháp và một đài cao lưu lời khắc của Thạch Trung Thiên.","detail":"Thạch Hạo tìm thấy tại đây lời hỏi Hạo nhi còn sống hay không. Dấu vết trận pháp cho thấy Thạch Trung Thiên từng dừng chân hoặc bế quan trên ngọn núi này.","theLucLienQuan":[],"nguon":["@c0632"]},{"id":"vung-nguyen-rua-truoc-mo-tien","name":"Vùng nguyền rủa trước Mộ tiên","cn":"","capDo":"khac","parentId":"mo-tien","blurb":"Khu vực bao quanh Mộ tiên, nơi nguyền rủa, lôi đình và áp lực tăng mạnh khi tiến gần ngôi mộ.","detail":"Sức nguyền rủa biến đổi theo tu vi người tiến vào. Thạch Hạo mất ba ngày ba đêm vượt một dặm cuối và thêm ba ngày mới đi hết mười bước cuối cùng để đến gần Mộ tiên.","theLucLienQuan":[],"nguon":["@c0635"]},{"id":"khu-phe-tich-than-bia-suc-chien-dau","name":"Khu phế tích có thần bia","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Khu phế tích trên đảo Ác Ma đặt thần bia cao ba ngàn trượng ghi bảng Sức chiến đấu.","detail":"Nơi này vẫn thu hút đông đảo cường giả tới quan sát và bàn luận. Lý Vân Thông trở lại đây rồi phát hiện khắc đồ Hoang đã đứng ở vị trí cao nhất trong thứ hạng cùng cấp.","theLucLienQuan":["Bất Lão sơn","Các đại giáo nổi danh"],"nguon":["@c0636"]},{"id":"hac-sac-sam-lam","name":"Hắc sắc Sâm lâm","cn":"","capDo":"khac","parentId":null,"blurb":"Một cấm địa từng giam chân Thạch Trung Thiên hơn mười năm.","detail":"Sau khi bị Tỳ Hưu truy sát, Thạch Trung Thiên mắc kẹt tại Hắc sắc Sâm lâm hơn mười năm trước khi thoát ra.","theLucLienQuan":[],"nguon":["@c0637"]},{"id":"co-quang","name":"Cổ quáng","cn":"","capDo":"khac","parentId":"dao-ac-ma","blurb":"Khu mỏ cổ có nguyền rủa đậm đặc, nơi Tần tộc từng quẳng Thạch Trung Thiên vào.","detail":"Trong cổ quáng, Thạch Trung Thiên đào được khối thủy tinh đỏ phong ấn chân huyết cấm kỵ. Sau khi nuốt một phần chân huyết, ông bùng phát sức mạnh để trốn thoát và thể ngộ phù văn.","theLucLienQuan":["Tần tộc"],"nguon":["@c0639"]},{"id":"bi-canh-ngu-hanh-chau","name":"Bí cảnh Ngũ hành châu","cn":"","capDo":"gioi-nho","parentId":"ngu-hanh-chau","blurb":"Tiểu thiên thế giới tại Ngũ hành châu, tương truyền do một Chí tôn thái cổ niết bàn thất bại để lại.","detail":"Bí cảnh chỉ mở một lần sau vài ngàn năm và hạn chế Giáo chủ tiến vào. Bên trong được truyền là có thánh dược, bảo huyết Chí tôn và truyền thừa, trở thành nơi các thiên tài nhiều giáo chuẩn bị tranh đoạt tạo hóa.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0639"]},{"id":"bi-canh-nguyen-thien","name":"Bí cảnh Nguyên Thiên","cn":"","capDo":"gioi-nho","parentId":"ngu-hanh-chau","blurb":"Bí cảnh nằm ở phía đông Ngũ hành châu, gần cổ thành Nguyên Thiên và sắp mở cửa cho các thiên kiêu.","detail":"Nơi đây gắn với cựu địa mà một vị Chí tôn thời Thái Cổ từng niết bàn. Các tu sĩ cho rằng bên trong có thần dược, chân huyết Chí tôn Thái Cổ và truyền thừa cấm kỵ, vì vậy nhiều sơ đại cùng truyền nhân đạo thống bất hủ tụ hội trước ngày mở cửa.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0640"]},{"id":"co-thanh-nguyen-thien","name":"Cổ thành Nguyên Thiên","cn":"","capDo":"thanh","parentId":"ngu-hanh-chau","blurb":"Cổ thành gần bí cảnh Nguyên Thiên, trở thành nơi tập trung của quần hùng trước khi bí cảnh mở.","detail":"Thành đông nghịt tu sĩ và thương nhân rao bán tư liệu liên quan đến bí cảnh. Nhiều chủng tộc hiếm, sơ đại và truyền nhân các đạo thống bất hủ lần lượt xuất hiện tại đây để chuẩn bị cho cuộc tranh đoạt tạo hóa.","theLucLienQuan":["Bất Lão sơn","Bổ Thiên giáo","Tiên điện","Tiệt Thiên giáo","Liên tộc","Tộc Hỏa Kim","Linh tộc"],"nguon":["@c0640"]},{"id":"khu-vuc-phong-an-trong-bi-canh-nguyen-thien","name":"Khu vực phong ấn trong bí cảnh Nguyên Thiên","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Vùng đất rộng khoảng trăm dặm có linh khí nồng đậm, cổ thụ khổng lồ và tử khí dâng lên từ phía Đông.","detail":"Toàn bộ khu vực bị đại trận Thần cấp cổ đại ngăn cách với bên ngoài và không có lối thoát thông thường. Những người cưỡng ép vượt qua ranh giới có thể bị phù văn giết chết; bên trong không thấy mãnh thú hay độc trùng.","theLucLienQuan":["Cung Hỏa Ma","Bộ tộc Xích vũ hạc"],"nguon":["@c0641"]},{"id":"son-coc-mau-tim","name":"Sơn cốc màu tím","cn":"","capDo":"khac","parentId":"khu-vuc-phong-an-trong-bi-canh-nguyen-thien","blurb":"Sơn cốc nằm tại trung tâm khu vực phong ấn, được bao quanh bởi những ngọn núi lớn tỏa khí tím.","detail":"Cung Hỏa Ma chiếm giữ các lối vào và tuyên bố sơn cốc là con đường duy nhất để rời khu vực. Bên trong có phế tích, Hoàng kim sơn, Lôi kích mộc, vườn dược cùng nhiều phù văn nguy hiểm.","theLucLienQuan":["Cung Hỏa Ma","Bộ tộc Xích vũ hạc"],"nguon":["@c0641"]},{"id":"phe-tich-thanh-tho-trong-son-coc","name":"Phế tích thánh thổ trong sơn cốc","cn":"","capDo":"khac","parentId":"son-coc-mau-tim","blurb":"Khu phế tích rộng lớn với đá lớn và mấy chục tòa cự cung đã sụp đổ.","detail":"Dấu tích kiến trúc và bố cục cho thấy nơi này từng có thể là một thánh thổ, nhưng hiện đã hoang phế và bị các cấm chế nguy hiểm bao phủ.","theLucLienQuan":["Cung Hỏa Ma"],"nguon":["@c0641"]},{"id":"hoang-kim-son","name":"Hoàng kim sơn","cn":"","capDo":"khac","parentId":"son-coc-mau-tim","blurb":"Ngọn núi vàng óng nằm giữa sơn cốc và không ngừng tỏa ánh sáng thần thánh.","detail":"Trên đỉnh Hoàng kim sơn mọc một cây Lôi kích mộc khổng lồ, thân cháy đen và quấn ánh chớp nhưng vẫn còn lá xanh tỏa thánh quang.","theLucLienQuan":["Cung Hỏa Ma"],"nguon":["@c0641"]},{"id":"xuong-so-long-ngao","name":"Xương sọ Long ngao","cn":"","capDo":"khac","parentId":"hoang-kim-son","blurb":"Không gian bên trong phần đầu của di cốt Long ngao tại Hoàng kim sơn.","detail":"Hơn hai mươi tu sĩ sống sót thoát ra từ đây. Bên trong xương sọ có một bồ đoàn, một bức tượng thần và tờ giấy vàng nghi chứa truyền thừa Long ngao.","theLucLienQuan":["Cung Hỏa Ma"],"nguon":["@c0642"]},{"id":"khu-vuc-khong-nguoi-cua-thuong-gioi","name":"Khu vực không người của thượng giới","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng đất rộng lớn của thượng giới chứa nhiều sinh linh và hiện tượng kỳ lạ có thể sát hại cả bá chủ lẫn Giáo chủ.","detail":"Nơi này từng có bãi bùn vàng giết bá chủ và giọt nước phát sáng làm thần hồn một Giáo chủ tan rã. Ma huyết quỷ thần thụ được cho là đến từ khu vực này, khiến Xích Lăng Không nghi Bí cảnh Nguyên Thiên có đường nối tới đó.","theLucLienQuan":[],"nguon":["@c0643"]},{"id":"ho-ngan-long-lien","name":"Hồ Ngân long liên","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Hồ nước trong veo nơi Ngân long liên sinh sống.","detail":"Đây là chiến trường giữa Thạch Hạo với Trần Thanh, Chân hống tử kim và cô gái Long tước; cuộc giao chiến khiến các thánh dược trong hồ lẩn xuống sâu.","theLucLienQuan":["Tiên điện","Bộ tộc Chân hống tử kim","Long tước tộc"],"nguon":["@c0644"]},{"id":"te-dan-loi-ra-bi-canh-nguyen-thien","name":"Tế đàn lối ra bí cảnh","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Điểm tiếp nhận những người được mệnh phù truyền khỏi bí cảnh.","detail":"Trần Thanh, Chân hống tử kim và cô gái Long tước lần lượt tái hiện tại đây sau khi bị Thạch Hạo đánh bại; các Giáo chủ cùng người bảo vệ bí cảnh chứng kiến sự việc.","theLucLienQuan":[],"nguon":["@c0644"]},{"id":"khu-vuc-tan-toc","name":"Khu vực Tần tộc","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Khu vực do Tần tộc nắm giữ bên trong bí cảnh.","detail":"Tần Trường Sinh đề nghị đưa Tử Tiêu Khôn tới đây để nhận sự hỗ trợ và phối hợp với người của Tần tộc.","theLucLienQuan":["Tần tộc"],"nguon":["@c0645"]},{"id":"dong-song-ngam-duoi-long-dat","name":"Dòng sông ngầm dưới lòng đất","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Dòng nước ngầm dài hàng trăm dặm nối linh hồ với một hồ nước lớn.","detail":"Dòng sông mang theo hương thơm và dấu vết của Ngân long liên, giúp Thạch Hạo lần theo thánh dược tới chiến trường hỗn loạn.","theLucLienQuan":[],"nguon":["@c0645"]},{"id":"ho-nuoc-khong-lo","name":"Hồ nước khổng lồ","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Hồ lớn nằm dưới chiến trường nơi nhiều thiên kiêu và sinh linh nhen nhóm Thần hỏa đang hỗn chiến.","detail":"Kiếm khí, thần lực và đạo văn liên tục đánh xuống mặt nước. Dưới hồ, Thạch Hạo phát hiện Nguyệt Thiền, đoạt hai cây Ngân long liên rồi giao chiến với nàng.","theLucLienQuan":["Bổ Thiên Giáo"],"nguon":["@c0645"]},{"id":"ho-nuoc-noi-tranh-doat-ngan-long-lien","name":"Hồ nước nơi tranh đoạt Ngân Long Liên","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Hồ nước nơi Thạch Hạo thu lấy Ngân Long Liên và giao chiến với Nguyệt Thiền.","detail":"Trận chiến diễn ra dưới đáy hồ khi Thạch Hạo truy đuổi các ánh bạc rồi thu được Ngân Long Liên. Kiếm quang của Nguyệt Thiền phá hủy đáy hồ và làm nước trong phạm vi hàng chục dặm bị rút cạn trước khi nước từ xa tràn về.","theLucLienQuan":["Bổ Thiên Giáo"],"nguon":["@c0646"]},{"id":"ngon-nui-trong-bi-canh-nguyen-thien","name":"Ngọn núi trong bí cảnh Nguyên Thiên","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Ngọn núi thấp có cây cỏ um tùm trong bí cảnh Nguyên Thiên.","detail":"Thạch Trung Thiên đứng tại đây quan sát Tần Hạo và bị một con gấu vàng cảnh giới Tôn Giả tập kích trước khi Thạch Hạo can thiệp.","theLucLienQuan":[],"nguon":["@c0647"]},{"id":"bi-canh-truyen-thua-nguyen-thien","name":"Bí cảnh truyền thừa Nguyên Thiên","cn":"","capDo":"gioi-nho","parentId":"ngu-hanh-chau","blurb":"Bí cảnh chứa các truyền thừa liên quan tới Chí tôn Nguyên Thiên.","detail":"Thạch Hạo và Thạch Trung Thiên muốn tìm bảo tàng cao nhất tại đây, đồng thời truy theo manh mối về áo nghĩa Lôi đạo thần bí và phần kinh văn còn thiếu.","theLucLienQuan":[],"nguon":["@c0649"]},{"id":"vung-nui-co-trong-bi-canh-nguyen-thien","name":"Vùng núi cổ trong bí cảnh Nguyên Thiên","cn":"","capDo":"vuc","parentId":"bi-canh-nguyen-thien","blurb":"Vùng núi rừng rậm rạp với cổ thụ, dây leo phát sáng và nhiều sinh linh nguy hiểm. Thạch Hạo cùng Đại ma thần gặp cóc thần vàng tại đây.","detail":"Khu vực có chim thần thuần huyết, cự xà Tôn Giả cảnh và nhiều độc trùng. Cóc thần vàng săn mồi trong vùng núi khiến hai ông cháu nhận ra bí cảnh có thể chứa sinh linh đã vượt Thần hỏa cảnh.","theLucLienQuan":[],"nguon":["@c0650"]},{"id":"ho-nuoc-va-nui-bi-pha-huy","name":"Hồ nước và núi bị phá hủy","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Khu vực còn lại sau cuộc tranh đoạt cốt phù giả. Thạch Hạo và Đại ma thần tìm hiểu âm mưu kích động các sơ đại tại đây.","detail":"Hồ nước và vùng núi xung quanh đã bị phá hủy trong tranh đấu. Những người còn lại xác nhận cốt phù xuất hiện trước đó là đồ giả do một kẻ giấu mặt tung ra.","theLucLienQuan":[],"nguon":["@c0650"]},{"id":"co-dia-moc-kim-huyet-thao","name":"Cổ địa mọc Kim huyết thảo","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Vùng đất cổ có Kim huyết thảo sinh trưởng. Thạch Hạo và Đại ma thần tới đây thu hoạch thánh dược thay vì tranh đoạt cốt phù.","detail":"Cổ địa chứa Kim huyết thảo, một chủ dược dùng luyện Bất diệt kim thân dịch và Kim cương dịch. Hai ông cháu tiến vào nơi này trong lúc sáu bảy khối cốt phù thật gây nên đại chiến ở nơi khác.","theLucLienQuan":["Thạch Tộc"],"nguon":["@c0650"]},{"id":"hon-dao-quang-mon","name":"Hòn đảo quang môn","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Hòn đảo phủ đầy phù văn với một quang môn giả mạo lối vào truyền thừa. Thiếu niên mặt trái táo bố trí sát trận tại đây để săn người mang cốt phù.","detail":"Tin chân huyết Chí Tôn xuất thế thu hút đông đảo tu sĩ tới đảo. Sát trận trong quang môn giết một sơ đại, làm trọng thương người thứ hai và gây thương vong cho nhiều người bên ngoài.","theLucLienQuan":[],"nguon":["@c0650"]},{"id":"quang-mon","name":"Quang môn","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Một quang môn trong bí cảnh, nơi linh thân có thể được dùng làm mồi đánh lạc hướng.","detail":"Sơ đại Thánh Vũ tộc định cho bộ linh thân tiến vào quang môn báo thù trong khi chân thân ẩn nấp tìm đường rời đi.","theLucLienQuan":["Thánh Vũ tộc"],"nguon":["@c0651"]},{"id":"co-dia-truyen-thua","name":"Cổ địa truyền thừa","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Cổ địa liên quan tới khu truyền thừa, nơi cốt phù được dùng làm lệnh bài tiến vào.","detail":"Sau khi đoạt cốt phù truyền thừa, Thạch Hạo cùng tổ phụ rời khu vực hỗn loạn và chuyển sang chủ động săn những kẻ thù trong bí cảnh.","theLucLienQuan":[],"nguon":["@c0651"]},{"id":"loi-ra-bi-canh","name":"Lối ra bí cảnh","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Nơi những người mất mệnh phù xuất hiện trở lại sau khi được đưa ra khỏi bí cảnh.","detail":"Các sơ đại trở về tại đây bị những người bên ngoài tra hỏi, khiến giới tu sĩ nhận định tranh đấu trong bí cảnh đang trở nên nguy hiểm hơn.","theLucLienQuan":[],"nguon":["@c0651","@c0678"]},{"id":"noi-sau-trong-bi-canh","name":"Nơi sâu trong bí cảnh","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Vùng núi sâu có linh tuyền, linh dược và nhiều chim thần dị thú, được hai ông cháu chọn làm nơi chữa thương và bế quan.","detail":"Khu vực có những dãy núi màu nâu phủ tử khí, linh tuyền, linh chi, lão dược và Xích Giao đằng. Thạch Hạo cùng Thạch Trung Thiên tránh khỏi sự chú ý của các tu sĩ bên ngoài, thu gom dược liệu rồi bế quan trùng tu tại đây.","theLucLienQuan":[],"nguon":["@c0656"]},{"id":"dong-thien-duy-nhat-cua-thach-hao","name":"Động Thiên duy nhất của Thạch Hạo","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian Động Thiên hợp nhất của Thạch Hạo, có thể được xem như một vực và nuôi dưỡng nhiều dấu ấn sinh linh.","detail":"Trong lần trùng tu Hóa Linh, nơi đây đồng thời hiện ra các dấu ấn Côn Bằng, Toan Nghê, Lôi Thiên tước và Chu Yếm. Thạch Hạo dùng những dấu ấn được nuôi dưỡng trong Động Thiên để hoàn thiện giai đoạn Động Thiên dưỡng linh.","theLucLienQuan":[],"nguon":["@c0656"]},{"id":"day-nui-noi-tan-toc-nghi-ngoi","name":"Dãy núi nơi Tần tộc nghỉ ngơi","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Khu vực nghỉ ngơi của lực lượng Tần tộc trong Bí cảnh Nguyên Thiên.","detail":"Thái Âm Ngọc Thỏ báo cho Thạch Hạo về hoạt động của Tần tộc tại khu vực này. Đôi sát thủ trẻ tuổi Thiên quốc cũng tới đây và bị hai ông cháu theo dõi.","theLucLienQuan":["Tần tộc","Thiên quốc"],"nguon":["@c0657"]},{"id":"rung-ram-noi-tan-toc-dung-chan","name":"Rừng rậm nơi Tần tộc dừng chân","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Khu rừng rậm nơi lực lượng Tần tộc dừng chân và tổ chức tìm kiếm Hoang.","detail":"Rừng có cổ thụ cao nghìn mét, lớp lá mục dày cùng nhiều độc trùng và mãnh thú. Tổ tôn Thạch Hạo ẩn trong khu vực này để giám sát hoạt động của Tần tộc.","theLucLienQuan":["Tần tộc"],"nguon":["@c0658"]},{"id":"ho-duoi-thac-nuoc-cua-bich-giao","name":"Hồ dưới thác nước của bích giao","cn":"","capDo":"khac","parentId":"bi-canh-nguyen-thien","blurb":"Hồ sâu dưới thác nước, nơi sinh trưởng củ ấu vàng cấp thánh dược.","detail":"Bích giao mạnh hơn sinh linh nhen nhóm Thần hỏa bình thường trấn giữ hồ. Tào Vũ Sinh lấy thánh dược tại đây, khiến bích giao thức tỉnh và truy sát cả ba người.","theLucLienQuan":[],"nguon":["@c0658"]},{"id":"tien-tri-cua-chi-ton-nguyen-thien","name":"Tiên trì của chí tôn Nguyên Thiên","cn":"","capDo":"khac","parentId":"bi-canh-truyen-thua-nguyen-thien","blurb":"Hồ tiên gắn với lần niết bàn thất bại của chí tôn Nguyên Thiên và là cửa ải dẫn tới nơi truyền thừa.","detail":"Khi trận pháp phong ấn bị vô tình vén mở, tinh khí tiên trì thoát ra, tạo ráng đỏ cùng thần quang kinh thiên. Dị tượng thu hút các sơ đại và truyền nhân mạnh tới tranh giành cơ hội tiến vào nơi truyền thừa.","theLucLienQuan":["Tiên điện","Tộc Hỏa Kim"],"nguon":["@c0658"]},{"id":"vung-nui-tien-tri","name":"Vùng núi tiên trì","cn":"","capDo":"khac","parentId":"bi-canh-truyen-thua-nguyen-thien","blurb":"Vùng núi bao quanh tiên trì, nơi các cường giả trẻ hội tụ trước cuộc tranh đoạt truyền thừa.","detail":"Truyền nhân Tiên điện, Nguyệt Thiền, Đằng Nhất, Thiểm Điện Tử, Chân Cổ cùng nhiều sơ đại xuất hiện tại đây với pháp khí và uy năng mạnh mẽ.","theLucLienQuan":["Tiên điện","Tộc Hỏa Kim"],"nguon":["@c0658"]},{"id":"noi-truyen-thua-than-bi","name":"Nơi truyền thừa thần bí","cn":"","capDo":"gioi-nho","parentId":"bi-canh-truyen-thua-nguyen-thien","blurb":"Không gian truyền thừa nằm sau một cánh cửa sáng phủ sương mù xuất hiện cạnh tiên trì.","detail":"Sự xuất hiện của cánh cửa khiến Tần tộc, cung Hỏa Ma và các sơ đại chuyển sang tranh nhau tiến vào. Bên trong có dị tượng, phù văn in dấu trong hư không và thần âm; Thạch Hạo cùng Đại ma thần đã xông vào.","theLucLienQuan":["Tần tộc","Cung Hỏa Ma"],"nguon":["@c0660"]},{"id":"vuc-sau-cam-khong","name":"Vực sâu cấm không","cn":"","capDo":"khac","parentId":"rung-da-thach-lam","blurb":"Vực sâu đen bị sương mù che phủ, có lực cắn nuốt mạnh và quy tắc cấm phi hành.","detail":"Đá rơi xuống vực rất lâu vẫn không có hồi âm. Những người tiến vào chỉ có thể dựa vào các thân cổ mộc bắc ngang để vượt sang bờ đối diện.","theLucLienQuan":["Tần tộc","Minh thổ"],"nguon":["@c0661"]},{"id":"nhung-cau-khi-co-moc","name":"Những cầu khỉ cổ mộc","cn":"","capDo":"khac","parentId":"vuc-sau-cam-khong","blurb":"Hơn mười thân cổ mộc màu đen bắc ngang vực sâu cấm không.","detail":"Các cây cầu là những con đường hiếm hoi để vượt vực, khiến các đội ngũ phải tranh nhau chiếm lối và tạo điều kiện cho những cuộc phục kích.","theLucLienQuan":["Tần tộc","Minh thổ"],"nguon":["@c0661"]},{"id":"chin-toa-thanh-son","name":"Chín tòa Thánh sơn","cn":"","aliases":["Chín ngọn núi tím","Chín ngọn thánh sơn màu tím","Chín tòa thần sơn"],"capDo":"khac","parentId":"rung-da-thach-lam","blurb":"Chín ngọn núi nguy nga tỏa ánh tím, là khu vực chứa truyền thừa Chí tôn mà các phe đang tranh đoạt.","detail":"Các ngọn núi xuất hiện ở khu vực trung tâm sau khi đoàn người vượt qua rừng đá và vực sâu. Nhiều sơ đại cùng thế lực giao chiến dữ dội quanh chân núi để giành đường tiến vào.","theLucLienQuan":["Thánh Vũ tộc"],"nguon":["@c0661"]},{"id":"cung-dien-truyen-thua-tren-dinh-thanh-son","name":"Cung điện truyền thừa trên đỉnh thánh sơn","cn":"","capDo":"khac","parentId":"chin-toa-thanh-son","blurb":"Mỗi ngọn trong chín thánh sơn đều có một cung điện truyền thừa trên đỉnh.","detail":"Cung điện chứa thần âm đại đạo, phù văn, kinh nghiệm và tâm đắc tu hành của chí tôn Nguyên Thiên. Khả năng cảm ngộ tại đây quyết định người nào được truyền tống tới cung điện cao nhất.","theLucLienQuan":[],"nguon":["@c0662"]},{"id":"cung-dien-tren-thanh-son-thu-sau","name":"Cung điện trên thánh sơn thứ sáu","cn":"","capDo":"khac","parentId":"chin-toa-thanh-son","blurb":"Cung điện do Tần tộc và Cung Hỏa Ma chiếm giữ để lĩnh hội tâm đắc của Chí tôn Nguyên Thiên.","detail":"Sau khi bị phá cơ duyên, Thạch Hạo cùng Thạch Trung Thiên xông vào đây, dùng lôi đình và nguyền rủa quấy nhiễu những người đang ngộ đạo.","theLucLienQuan":["Tần tộc","Cung Hỏa Ma"],"nguon":["@c0663"]},{"id":"vo-dai-tren-khong","name":"Võ đài trên không","cn":"","capDo":"khac","parentId":"chin-toa-thanh-son","blurb":"Chiến trường rộng lớn lơ lửng trên không trung, có thể được quan sát từ chín tòa thánh sơn.","detail":"Quy tắc truyền thừa đưa những người tham gia tranh chấp lên võ đài và dập tắt Thần hỏa của các cường giả, buộc mọi bên phân thắng bại ở cùng cấp độ.","theLucLienQuan":["Tần tộc","Cung Hỏa Ma"],"nguon":["@c0663"]},{"id":"toa-than-son-thu-sau","name":"Tòa thần sơn thứ sáu","cn":"","capDo":"khac","parentId":"chin-toa-thanh-son","blurb":"Một trong chín tòa Thánh sơn, nơi nhóm tu sĩ Tần tộc đứng quan chiến.","detail":"Từ tòa thần sơn thứ sáu, những người Tần tộc chứng kiến các cao thủ Thần Hỏa cảnh trong tộc liên tiếp bị Thạch Hạo giết chết trên võ đài.","theLucLienQuan":["Tần tộc"],"nguon":["@c0664"]},{"id":"mo-binh","name":"Mộ binh","cn":"","capDo":"khac","parentId":"cung-dien-cao-nhat","blurb":"Khu mộ binh nằm trong cổ điện cao nhất, nơi mai táng chiến y hư hại của Chí tôn Nguyên Thiên.","detail":"Mộ binh dùng thạch anh mai táng chiến y Thiên Khuyết thạch, đồng thời cất chín bộ giáp Thiên Thần và nhiều thần liệu, khiến các cường giả lập tức tranh đoạt.","theLucLienQuan":[],"nguon":["@c0667"]},{"id":"dao-dai-hoang-kim","name":"Đạo đài hoàng kim","cn":"","capDo":"khac","parentId":"cung-dien-cao-nhat","blurb":"Đạo đài khổng lồ như núi dùng để tuyển chọn người tiếp nhận truyền thừa Nguyên Thiên.","detail":"Đạo đài có hàng trăm bồ đoàn, áp lực cấm phi hành và kinh văn được trao theo mức lĩnh hội cùng độ cao. Người tham dự phải vừa ngộ đạo, chiến đấu vừa leo lên đỉnh để tranh cốt thư truyền thừa.","theLucLienQuan":[],"nguon":["@c0667"]},{"id":"cung-dien-cao-nhat","name":"Cung điện cao nhất","cn":"","aliases":["Cung điện chí cao","Cổ điện cao nhất","Cung điện truyền thừa cao nhất của chí tôn Nguyên Thiên"],"capDo":"khac","parentId":"chin-toa-thanh-son","blurb":"Cổ điện cao nhất trong khu truyền thừa của Chí tôn Nguyên Thiên.","detail":"Không gian bên trong bao la, ngập khí hỗn độn và mang hơi thở thời gian, chứa Mộ binh cùng đạo đài hoàng kim dùng cho thử thách truyền thừa.","theLucLienQuan":[],"nguon":["@c0667"]},{"id":"co-dien","name":"Cổ điện","cn":"","capDo":"khac","parentId":null,"blurb":"Cổ điện chứa đạo đài hoàng kim và là nơi Thạch Hạo quyết đấu với truyền nhân trẻ tuổi Tiên điện.","detail":"Sức mạnh phát ra khi Nhân Tiên Ấn được thi triển khiến toàn bộ cổ điện chấn động.","theLucLienQuan":["Tiên điện"],"nguon":["@c0669"]},{"id":"ngoai-gioi-bi-canh","name":"Ngoại giới bí cảnh","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực bên ngoài bí cảnh, nơi các Giáo chủ và đông đảo tu sĩ theo dõi tế đàn lối ra.","detail":"Tại đây, những người chứng kiến kinh ngạc khi truyền nhân Tiên điện tái sinh sau thất bại và khi Thạch Hạo tiếp tục truy sát người của Tiên điện ngay trên tế đàn.","theLucLienQuan":["Tiên điện"],"nguon":["@c0672"]},{"id":"te-dan","name":"Tế đàn","cn":"","capDo":"khac","parentId":"ngoai-gioi-bi-canh","blurb":"Nơi Thạch Hạo bất ngờ xuất hiện và tập kích phe Tiên điện.","detail":"Thạch Hạo đánh chết đầy tớ của truyền nhân Tiên điện, đẩy đối thủ rơi khỏi tế đàn rồi mượn lực phản chấn để lùi trở lại bí cảnh.","theLucLienQuan":["Tiên điện"],"nguon":["@c0673"]},{"id":"khu-vuc-khong-nguoi","name":"Khu vực không người","cn":"","capDo":"vuc","parentId":null,"blurb":"Một khu vực đặc biệt gắn với nguồn gốc bộ giáp rách của Thạch Hạo.","detail":"Tần Trường Sinh xác nhận bộ giáp rách của Thạch Hạo đến từ khu vực không người và đã nhiễm khí tức đặc biệt tại đó.","theLucLienQuan":[],"nguon":["@c0673","@c0678"],"aliases":["Cấm khu"]},{"id":"cung-loi-de","name":"Cung Lôi Đế","cn":"","capDo":"khac","parentId":"khu-vuc-khong-nguoi","blurb":"Phế tích thần bí nằm sâu trong Cấm khu ngoài ba ngàn châu. Đây là nguồn gốc của truyền thừa Lôi Đế trên hai tờ giấy vàng.","detail":"Hình chiếu cho thấy núi đen gãy đổ, cung điện vàng sụp nát, dòng sông bạc khô cạn và lôi điện bao phủ. Chí tôn Nguyên Thiên từng giao chiến với một sinh linh bí ẩn tại đây trước khi trọng thương mang truyền thừa ra ngoài.","theLucLienQuan":[],"nguon":["@c0677"]},{"id":"dau-moi-khong-gian-trong-bi-canh","name":"Đầu mối không gian trong bí cảnh","cn":"","capDo":"khac","parentId":"bi-canh-cua-chi-ton-nguyen-thien","blurb":"Thông đạo không gian bất ổn do Ma huyết quỷ thần thụ phát hiện, có thể đưa người rời bí cảnh bằng một lối khác.","detail":"Điểm đến có thể cách hàng chục triệu dặm hoặc vượt qua nhiều châu. Thạch Hạo cùng các đồng hành dùng nơi này tránh vòng kiểm soát của các Giáo chủ tại cửa chính.","theLucLienQuan":[],"nguon":["@c0678","@c0679"]},{"id":"bi-canh-cua-chi-ton-nguyen-thien","name":"Bí cảnh của chí tôn Nguyên Thiên","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Bí cảnh giàu bảo dược nhưng áp chế sinh linh và khó cho phép vượt qua Thần Hỏa cảnh.","detail":"Hơn trăm năm một lần, quy tắc đại kiếp trong bí cảnh tiêu diệt những sinh linh vượt giới hạn. Ma huyết quỷ thần thụ phải tự phong ấn và dung hợp với di cốt Thiểm điện ngao để tránh quy tắc này.","theLucLienQuan":["Đạo thống chí tôn Nguyên Thiên"],"nguon":["@c0678"]},{"id":"ma-chau","name":"Ma Châu","cn":"","capDo":"chau","parentId":null,"blurb":"Đại châu cách Ngũ Hành Châu hàng chục châu, mang tên do thời cổ từng sinh ra Ma.","detail":"Ma Châu từng trải qua chiến tranh và sát phạt kéo dài. Ma Quỳ viên tọa lạc tại đây, trong vùng đất có thiên tinh cùng thụy hoa phong phú.","theLucLienQuan":["Ma Quỳ viên"],"nguon":["@c0679","@c0696"]},{"id":"day-nui-lua-ma-chau","name":"Dãy núi lửa Ma Châu","cn":"","capDo":"khac","parentId":"ma-chau","blurb":"Dãy núi lửa nóng rực, nơi Thạch Hạo và Thạch Trung Thiên xuất hiện sau khi vượt đầu mối không gian.","detail":"Khu vực có dung nham, khói đen và mùi lưu huỳnh. Hai ông cháu chọn nơi vắng người này để bế quan lĩnh hội Lôi đạo, sau đó Thạch Trung Thiên quyết định ở lại ẩn cư và tiếp tục tu hành.","theLucLienQuan":[],"nguon":["@c0679"]},{"id":"binh-nguyen-dat-vang-ma-chau","name":"Bình nguyên đất vàng Ma Châu","cn":"","capDo":"khac","parentId":"ma-chau","blurb":"Bình nguyên cằn cỗi rộng hơn mười vạn dặm, hầu như không có đạo thống tu hành.","detail":"Vùng đất vàng hoang vu có ít sinh linh mạnh mẽ. Tương truyền một đại năng viễn cổ từng phun ra ngọn lửa thiêu trụi nơi này trong chiến tranh.","theLucLienQuan":[],"nguon":["@c0679"]},{"id":"binh-nguyen-hoa-diem","name":"Bình nguyên hỏa diễm","cn":"","capDo":"vuc","parentId":"ma-chau","blurb":"Vùng đất chết rộng mấy vạn dặm tại Ma châu.","detail":"Bình nguyên được hình thành từ một ngọn lửa do đại năng viễn cổ phun ra. Sau thời gian dài, nơi đây vẫn hiếm sinh linh và thưa cỏ cây.","theLucLienQuan":[],"nguon":["@c0680"]},{"id":"thien-chau","name":"Thiên châu","cn":"","capDo":"chau","parentId":null,"blurb":"Một trong những châu mạnh nhất thượng giới và nằm giáp Ma châu.","detail":"Thiên châu là cái nôi của Thiên Nhân tộc. Thạch Hạo chọn vượt biên giới tới đây để tìm truyền tống trận đi sang những châu khác.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0680","@c0683"]},{"id":"binh-nguyen-mau-mau","name":"Bình nguyên màu máu","cn":"","capDo":"vuc","parentId":null,"blurb":"Chiến trường cổ rộng khoảng mười vạn dặm nằm giữa Ma châu và Thiên châu.","detail":"Bình nguyên màu máu tập trung nhiều hung nhân và cường giả chặn giết người qua đường. Trong biến cố tại chương này, toàn khu vực bị mười hai Ma vương dùng đại trận cổ phong cấm hư không.","theLucLienQuan":["Mười hai Ma vương bình nguyên màu máu","Đoàn lính đánh thuê Luân hồi"],"nguon":["@c0680"]},{"id":"thanh-toi-ac","name":"Thành Tội Ác","cn":"","capDo":"thanh","parentId":"binh-nguyen-mau-mau","blurb":"Một trong mười hai tòa thành lớn trên bình nguyên màu máu.","detail":"Thành trì là nơi nhiều chủng loại sinh linh và tội phạm tụ tập. Thạch Hạo nghe tin về biến cố biến thiên và gặp lại một thiếu nữ quen thuộc tại đây.","theLucLienQuan":[],"nguon":["@c0680"]},{"id":"the-gioi-tao-hoa-tien-co","name":"Thế giới tạo hóa Tiên cổ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Thế giới có nguồn gốc từ kỷ nguyên Tiên cổ và là mục tiêu của cuộc tranh đoạt tạo hóa giữa các thiên tài thượng giới.","detail":"Theo tin tức Thạch Hạo thu thập được, chỉ người ở cảnh giới Tôn giả mới có thể tiến vào thế giới này. Nhiều thiên tài đã đủ sức nhóm Thần hỏa vẫn chủ động áp chế cảnh giới để giữ tư cách tranh đoạt tạo hóa.","theLucLienQuan":[],"nguon":["@c0680"]},{"id":"day-nui-cuoi-tam-mat","name":"Dãy núi cuối tầm mắt","cn":"","capDo":"khac","parentId":"ma-chau","blurb":"Dãy núi nơi mục tiêu của Thiên Thần áo bạc chạy tới sau khi tách khỏi đoàn người.","detail":"Một trận đại chiến cấp Thiên Thần bùng phát tại đây, làm nhiều đỉnh núi nổ tung. Thiên Thần áo bạc rời bình nguyên màu máu và tiến vào dãy núi để tiếp tục truy sát mục tiêu.","theLucLienQuan":[],"nguon":["@c0682"]},{"id":"toa-thanh-da-do","name":"Tòa thành đá đỏ","cn":"","capDo":"thanh","parentId":"binh-nguyen-mau-mau","blurb":"Một trong mười hai tòa thành lớn trên bình nguyên màu máu.","detail":"Tòa thành được dựng bằng đá đỏ và mang nhiều dấu vết thời gian. Thạch Hạo cùng Vân Hi tạm dừng tại đây để tránh sóng gió từ cuộc giao tranh giữa các Thiên Thần.","theLucLienQuan":["Mười hai Ma vương bình nguyên màu máu"],"nguon":["@c0683"]},{"id":"di-tich-chien-truong-thuong-co","name":"Di tích chiến trường thượng cổ","cn":"","capDo":"khac","parentId":"binh-nguyen-mau-mau","blurb":"Những di tích nguy hiểm nằm ngoài tuyến đường an toàn trên bình nguyên màu máu.","detail":"Các di tích có thể bị âm vụ và quỷ vật bao phủ quanh năm. Tiên huyết cùng âm khí tại đây nuôi dưỡng Huyết Hồn thảo, khiến tu sĩ vẫn mạo hiểm tiến vào tìm kiếm.","theLucLienQuan":[],"nguon":["@c0683"]},{"id":"khu-co-dia-cua-thien-menh-thach","name":"Khu cổ địa của Thiên Mệnh thạch","cn":"","capDo":"khac","parentId":null,"blurb":"Địa phương đặc thù từng xuất hiện sáu viên Thiên Mệnh thạch vào thời thái cổ.","detail":"Sáu thiên tài Thiên Nhân tộc từng tiến vào khu cổ địa này, tìm được sáu viên Thiên Mệnh thạch và hoàn thành tiến hóa đến cực hạn. Trong đời hiện tại, Thiên Nhân tộc lại tiến vào đây tìm kỳ thạch, nhưng vị trí cụ thể chưa được tiết lộ.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0683"]},{"id":"chien-truong-mau-mau","name":"Chiến trường màu máu","cn":"","capDo":"khac","parentId":null,"blurb":"Một tuyệt địa ngập âm khí, âm vụ và quỷ vật, được Thạch Hạo chọn làm nơi cắt đuôi truy binh.","detail":"Khi không còn đường lui, Thạch Hạo cõng Vân Hi tiến vào chiến trường màu máu. Âm vụ dày đặc bên trong có thể ngăn cách khí tức với bên ngoài, nhưng nơi này cũng có quỷ vật hoành hành.","theLucLienQuan":[],"nguon":["@c0684"]},{"id":"chien-truong-thuong-co","name":"Chiến trường thượng cổ","cn":"","capDo":"khac","parentId":"ma-chau","blurb":"Bình nguyên cổ rộng hơn mười vạn dặm, bị máu thần ma nhuộm đỏ và bao phủ bởi sương máu cùng âm khí. Nơi đây còn lưu nhiều di vật chiến tranh và các sinh linh dị biến.","detail":"Chiến trường có trường mâu, khiên mục nát và di cốt thần ma từ thời viễn cổ. Sương máu cùng âm khí che phủ nhiều khu vực, còn đàn vượn ma chuyên luyện thể chiếm giữ một phần lãnh địa và tấn công sinh linh xâm nhập.","theLucLienQuan":["Đoàn lính đánh thuê Bách Cầm"],"nguon":["@c0685"]},{"id":"lanh-dia-vuon-ma","name":"Lãnh địa vượn ma","cn":"","capDo":"khac","parentId":"chien-truong-thuong-co","blurb":"Khu vực thuộc chiến trường thượng cổ, nơi nhiều vượn ma sống đoàn kết và chống lại mọi sinh linh xâm nhập. Đàn vượn tại đây từng đánh tan một bộ phận đoàn Bách Cầm.","detail":"Vượn ma trong khu vực phối hợp tập kích từ núi cao và sương mù, dùng thể phách chống thần hỏa cùng phù văn. Cuộc giao chiến tại đây khiến đoàn Bách Cầm mất mười một cường giả, gồm hai sinh linh cấp Thần.","theLucLienQuan":["Đoàn lính đánh thuê Bách Cầm"],"nguon":["@c0685"]},{"id":"chien-truong-co","name":"Chiến trường cổ","cn":"","capDo":"vuc","parentId":null,"blurb":"Một chiến trường rộng lớn phủ sương mù, nơi Thạch Hạo và Vân Hi chạm trán chín vượn ma Thần Hỏa cảnh.","detail":"Khu vực này có lãnh địa và sào huyệt của chín vượn ma chuyên luyện thể cực hạn. Gần sào huyệt mọc hơn năm mươi cây Huyết Hồn thảo quý hiếm.","theLucLienQuan":[],"nguon":["@c0686"]},{"id":"sao-huyet-vuon-ma","name":"Sào huyệt vượn ma","cn":"","capDo":"khac","parentId":"chien-truong-co","blurb":"Sào huyệt gồm vài hang đá nằm trên một sườn dốc tại chiến trường cổ.","detail":"Phía dưới sườn dốc mọc hơn năm mươi cây Huyết Hồn thảo. Các hang đá không chứa vật gì trực tiếp giải đáp bí mật miễn dịch pháp lực mà Thạch Hạo tìm kiếm.","theLucLienQuan":[],"nguon":["@c0686"]},{"id":"chien-truong-vien-co-dau-tien","name":"Chiến trường viễn cổ đầu tiên","cn":"","capDo":"khac","parentId":null,"blurb":"Một khu ma thổ phủ sương mù, có vượn ma và sinh linh Chân Nhất cảnh hoạt động.","detail":"Thạch Hạo và Vân Hi gặp ba con vượn ma cùng một bộ xương trắng mang lửa thần, cầm cốt kiếm và có tu vi Chân Nhất cảnh tại đây. Hai người phải chạy xa hơn vạn dặm mới thoát khỏi khu di tích.","theLucLienQuan":[],"nguon":["@c0687"]},{"id":"chien-truong-co-nam-van-dam","name":"Chiến trường cổ năm vạn dặm","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường cổ rộng khoảng năm vạn dặm, chứa hài cốt Thiên Thần và nhiều di vật chiến tranh đã hư hỏng.","detail":"Khu vực có âm khí, sương mù, hài cốt Thiên Thần cùng nhiều binh khí và bảo cụ mục nát. Thạch Hạo và Vân Hi tìm thấy sáu cây Huyết Hồn thảo rải rác, sau đó phát hiện một cụm hơn hai trăm cây dưới núi đá và giao chiến với hai vượn ma canh giữ.","theLucLienQuan":[],"nguon":["@c0687"]},{"id":"chien-truong","name":"Chiến trường","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực giao tranh mà Thạch Hạo và Vân Hi tiếp tục tiến sâu vào.","detail":"Sau khi đánh gục cường giả trẻ tuổi của Chiến tộc, Thạch Hạo cùng Vân Hi hướng về nơi sâu trong chiến trường.","theLucLienQuan":["Chiến tộc","Thiên Nhân tộc"],"nguon":["@c0691"]},{"id":"cot-son","name":"Cốt sơn","cn":"","capDo":"khac","parentId":"chien-truong","blurb":"Ngọn núi cao mấy ngàn trượng được tạo thành từ vô số hài cốt và có hình dáng một ngôi mộ lớn. Dưới chân núi có Cốt thần cầm đao ngủ đông, còn Quả Kim Bồ sinh trưởng gần đó.","detail":"Cốt sơn được cấu thành từ hài cốt của hoàng kim Cự nhân, Giao và Nhân tộc. Địa thế hình ngôi mộ cùng Chân Thần trấn giữ khiến nơi này trở thành một khu vực cực kỳ nguy hiểm trong chiến trường thời viễn cổ.","theLucLienQuan":["Đoàn lính đánh thuê Bách Cầm","Chiến tộc"],"nguon":["@c0692"]},{"id":"huyet-tri-duoi-mo-lon","name":"Huyết trì dưới mộ lớn","cn":"","capDo":"khac","parentId":"cot-son","blurb":"Huyết trì rộng hàng chục dặm nằm sâu dưới cốt sơn, nơi một sinh linh khổng lồ đang được thai nghén.","detail":"Máu trong trì cuộn như sóng biển và tỏa ra khí thế đáng sợ. Khi bị lôi đình công kích, nơi đây bùng phát tràng vực đủ sức phá hủy bí bảo và uy hiếp Chân Thần.","theLucLienQuan":[],"nguon":["@c0693"]},{"id":"mo-xuong","name":"Mộ xương","cn":"","capDo":"khac","parentId":"cot-son","blurb":"Không gian bí ẩn nằm dưới cốt sơn và bao quanh khu vực huyết trì.","detail":"Cốt thần lao vào mộ xương khi sinh linh được hắn gọi là đại nhân bị quấy nhiễu, cho thấy nơi đây là khu vực trọng yếu mà hắn trấn giữ.","theLucLienQuan":[],"nguon":["@c0693"]},{"id":"khu-co-dia-co-cot-son","name":"Khu cổ địa có cốt sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Khu cổ địa nơi cây Kim Bồ sinh trưởng và cuộc đại chiến giữa Cốt thần với ba Chân Thần diễn ra.","detail":"Khu vực có cốt sơn chứa pháp đao Thiên Thần và một trường vực sâu dưới lòng đất. Sau một đợt chấn động, trường vực biến mất; nhiệm vụ gắn với cốt sơn cũng khiến Cốt thần không thể rời nơi này quá xa.","theLucLienQuan":["Chiến tộc"],"nguon":["@c0694"]},{"id":"ngon-nui-da-nguoi-dan-ba-chien-toc-nghi-thuong","name":"Ngọn núi đá","cn":"","capDo":"khac","parentId":"khu-co-dia-co-cot-son","blurb":"Nơi Nữ Chân Thần Chiến tộc dừng lại trị thương sau khi thoát khỏi cuộc truy sát của Cốt thần.","detail":"Nữ Chân Thần Chiến tộc đáp xuống đây, uống linh đan và đả tọa vì thương thế quá nặng. Thạch Hạo âm thầm áp sát rồi phát động thần thông Luân Hồi tại địa điểm này.","theLucLienQuan":["Chiến tộc"],"nguon":["@c0694"]},{"id":"day-nui-an-nau-cua-long-tuoc","name":"Dãy núi ẩn náu của Long tước","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực Long tước chạy tới ẩn náu sau khi bị trọng thương.","detail":"Long tước dùng bí pháp chạy tới dãy núi này sau khi mất hai cánh và bị thương nặng. Thạch Hạo dựa vào vết máu cùng kinh nghiệm săn thú tích lũy ở Đại hoang để lần theo nó.","theLucLienQuan":["Đoàn lính đánh thuê Bách Cầm"],"nguon":["@c0695"]},{"id":"son-coc-cua-long-tuoc","name":"Sơn cốc của Long tước","cn":"","capDo":"khac","parentId":"day-nui-an-nau-cua-long-tuoc","blurb":"Sơn cốc nơi Long tước dừng lại chữa thương trước khi bị Thạch Hạo tìm thấy.","detail":"Long tước ẩn trong sơn cốc với hai cánh đã mất và một móng vuốt bị hỏng, đồng thời dùng đan dược để duy trì tính mạng và chữa trị. Thạch Hạo lần theo dấu vết tới đây rồi giao chiến với nó.","theLucLienQuan":["Đoàn lính đánh thuê Bách Cầm"],"nguon":["@c0695"]},{"id":"thien-ngoai","name":"Thiên ngoại","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian ngoài thiên địa được chọn làm nơi quyết chiến giữa Chiến Đế và lão Thiên Nhân.","detail":"Lão Thiên Nhân đề nghị chuyển trận chiến tới thiên ngoại để hai người có thể giao đấu mà không trực tiếp phá hủy bình nguyên màu máu.","theLucLienQuan":["Thiên Nhân tộc","Chiến tộc"],"nguon":["@c0696"]},{"id":"chien-truong-vien-co","name":"Chiến trường viễn cổ","cn":"","capDo":"vuc","parentId":"binh-nguyen-mau-mau","blurb":"Khu vực viễn cổ rộng hai mươi vạn dặm nằm trong bình nguyên màu máu.","detail":"Chiến trường bị sương mù và quy tắc kỳ lạ ngăn cách, còn lưu lại máu, xương cùng dấu tích đạo hạnh của một chí cường giả đã chết. Thạch Hạo và Vân Hi chạy sâu vào khu vực này để tránh các đội quân truy sát.","theLucLienQuan":["Thiên Nhân tộc","Chiến tộc"],"nguon":["@c0697"]},{"id":"muoi-hai-toa-thanh-toi-ac","name":"Mười hai tòa thành Tội Ác","cn":"","capDo":"thanh","parentId":"binh-nguyen-mau-mau","blurb":"Mười hai tòa thành đã đổ nát trên bình nguyên màu máu.","detail":"Các phế thành được dùng làm trung tâm cho nhiều khu vực chiến đấu lan rộng vào chiến trường viễn cổ.","theLucLienQuan":["Mười hai thành Tội Ác"],"nguon":["@c0697"]},{"id":"noi-sau-nhat-cua-chien-truong-vien-co","name":"Nơi sâu nhất của chiến trường viễn cổ","cn":"","capDo":"khac","parentId":"chien-truong-vien-co","blurb":"Khu vực sâu trong chiến trường viễn cổ mà Thạch Hạo tới sau cuộc truy sát kéo dài hơn mười vạn dặm.","detail":"Nơi đây có ba vầng huyết nguyệt, sương mù, tiếng thần ma gào thét và mặt đất khô cứng như sắt đá. Thạch Hạo dùng thuật độn thổ tiến vào khu vực này, sau đó quay lại đối diện Chiến vương.","theLucLienQuan":["Chiến Đế tộc","Chiến tộc"],"nguon":["@c0698"]},{"id":"cam-khu-khong-nguoi-rong-lon","name":"Cấm khu không người rộng lớn","cn":"","capDo":"vuc","parentId":null,"blurb":"Cấm khu rộng lớn từng được Thạch Hạo tiến vào và mang ra một loại đất vàng đặc biệt.","detail":"Bùn vàng lấy từ nơi này có khả năng ăn mòn hoa văn, làm Ngọc Tịnh bình gần cấp Thiên Thần mất hiệu lực.","theLucLienQuan":[],"nguon":["@c0698"]},{"id":"chien-truong-duoi-ba-vang-huyet-nguyet","name":"Chiến trường dưới ba vầng huyết nguyệt","cn":"","capDo":"khac","parentId":"chien-truong","blurb":"Chiến trường lạnh lẽo dưới ánh đỏ của ba vầng huyết nguyệt.","detail":"Khu vực có mặt đất khô cứng, lạnh lẽo và phủ sương, nơi Thạch Hạo quyết chiến với Chiến Thiên Ca.","theLucLienQuan":["Chiến tộc","Chiến Đế tộc"],"nguon":["@c0699"]},{"id":"trung-tam-chien-truong-co","name":"Trung tâm chiến trường cổ","cn":"","capDo":"khac","parentId":"chien-truong-vien-co","blurb":"Khu vực trung tâm nguy hiểm của chiến trường cổ, tương truyền từng có một cao thủ tuyệt thế tọa hóa.","detail":"Máu, xương và phù văn của cao thủ tọa hóa vương vãi trong khu vực này. Những xích thần trật tự đứt gãy tồn tại khắp nơi và có thể cắt lìa thân thể sinh linh đến gần.","theLucLienQuan":[],"nguon":["@c0700"]},{"id":"trung-tam-cam-dia","name":"Trung tâm cấm địa","cn":"","capDo":"khac","parentId":"trung-tam-chien-truong-co","blurb":"Vùng sâu khó tiếp cận bên trong trung tâm chiến trường cổ, được bao quanh bởi bạch cốt và quy tắc xích thần nguy hiểm.","detail":"Bên trong cấm địa có cây cỏ, dây leo và hoa phát sáng, trái ngược với vùng bạch cốt ở bên ngoài. Thạch Hạo dùng Trùng đồng quan sát và phát hiện một cô gái tuyết y đang đứng tại đây.","theLucLienQuan":[],"nguon":["@c0700"]}]};
